import React, { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Settings, Users, UserPlus, Copy, Check, Shield, Trash2,
  AlertTriangle, Sparkles, Mail, Globe, Crown, Eye, User,
  Palette, Info, EyeOff
} from "lucide-react";
import { useWorkspace } from "../context/WorkspaceContext";
import { useAuth } from "../context/AuthContext";
import { Avatar } from "../components/layout/Sidebar";

const ICONS = ["🏢", "🚀", "⚡", "🎯", "🛠️", "🌟", "🔥", "💡", "🎨", "📦"];
const COLORS = [
  "#6366f1", // Indigo
  "#8b5cf6", // Violet
  "#ec4899", // Pink
  "#14b8a6", // Teal
  "#f97316", // Orange
  "#eab308", // Yellow
  "#22c55e", // Green
  "#3b82f6"  // Blue
];

const ROLE_META = {
  owner:  { icon: Crown,  color: "#eab308", bg: "rgba(234,179,8,0.1)",  label: "Owner" },
  admin:  { icon: Shield, color: "#a78bfa", bg: "rgba(167,139,250,0.1)", label: "Admin" },
  member: { icon: User,   color: "#94a3b8", bg: "rgba(148,163,184,0.1)", label: "Member" },
  viewer: { icon: Eye,    color: "#0ea5e9", bg: "rgba(14,165,233,0.1)",  label: "Viewer" }
};

const TabButton = ({ label, active, onClick, icon: Icon, badge }) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-2 px-6 py-3 rounded-xl text-sm font-semibold
      transition-all duration-200 relative
      ${active
        ? "bg-violet-500/10 text-violet-400"
        : "text-slate-400 hover:text-slate-200 hover:bg-slate-800/40"
      }`}
  >
    <Icon size={16} />
    <span>{label}</span>
    {badge != null && (
      <span className={`px-2 py-0.5 rounded-full text-xs font-bold transition-all
        ${active ? "bg-violet-500/20 text-violet-400" : "bg-slate-800 text-slate-500"}`}>
        {badge}
      </span>
    )}
    {active && (
      <span className="absolute bottom-0 left-6 right-6 h-0.5 bg-violet-500 rounded-t" />
    )}
  </button>
);

const Field = ({ label, description, children }) => (
  <div className="space-y-2">
    <div>
      <label className="block text-sm font-bold text-white">{label}</label>
      {description && <p className="text-xs text-slate-500 mt-0.5 leading-relaxed">{description}</p>}
    </div>
    {children}
  </div>
);

const WorkspaceSettings = () => {
  const { workspaceId } = useParams();
  const navigate = useNavigate();
  const { activeWorkspace, updateWorkspace, inviteMember } = useWorkspace();
  const { user } = useAuth();

  const [activeTab, setActiveTab] = useState("general");
  const [form, setForm] = useState({
    name:        activeWorkspace?.name        || "",
    description: activeWorkspace?.description || "",
    icon:        activeWorkspace?.icon        || "🏢",
    color:       activeWorkspace?.color       || "#6366f1",
  });
  const [saving, setSaving]       = useState(false);
  const [saved, setSaved]         = useState(false);
  const [saveError, setSaveError] = useState("");

  const [inviteEmail, setInviteEmail]   = useState("");
  const [inviteRole, setInviteRole]     = useState("member");
  const [inviting, setInviting]         = useState(false);
  const [inviteResult, setInviteResult] = useState(null);
  const [copiedLink, setCopiedLink]     = useState(false);

  const userRole = activeWorkspace?.members?.find((m) => m.user?._id === user?._id)?.role;
  const canEdit  = ["owner", "admin"].includes(userRole);
  const totalMembers = activeWorkspace?.members?.length || 0;

  const handleSave = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;
    setSaving(true);
    setSaveError("");
    const result = await updateWorkspace(workspaceId || activeWorkspace?._id, form);
    setSaving(false);
    if (result.success) {
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
    } else {
      setSaveError(result.message);
    }
  };

  const handleInvite = async (e) => {
    e.preventDefault();
    if (!inviteEmail) return;
    setInviting(true);
    setInviteResult(null);
    const result = await inviteMember(workspaceId || activeWorkspace?._id, inviteEmail, inviteRole);
    setInviting(false);
    setInviteResult(result);
    if (result.success) setInviteEmail("");
  };

  const copyLink = () => {
    if (inviteResult?.invite?.inviteLink) {
      navigator.clipboard.writeText(inviteResult.invite.inviteLink);
      setCopiedLink(true);
      setTimeout(() => setCopiedLink(false), 2000);
    }
  };

  if (!activeWorkspace) {
    return (
      <div className="flex items-center justify-center h-full text-slate-500 bg-slate-950">
        <div className="text-center space-y-2">
          <Settings size={28} className="mx-auto text-slate-600 animate-spin" />
          <p className="text-sm font-medium">Select a workspace first.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full min-h-full bg-slate-950/20 px-8 py-8 space-y-8">

      {/* ── Header Banner Card ──────────────────────────────────────── */}
      <div
        className="relative rounded-2xl overflow-hidden p-8 border animate-fade-in"
        style={{
          background: form.color
            ? `linear-gradient(135deg, ${form.color}18, ${form.color}05, transparent)`
            : "linear-gradient(135deg, rgba(124,58,237,0.1), transparent)",
          borderColor: `${form.color || "#7c3aed"}20`,
        }}
      >
        {/* Glow orbs */}
        <div
          className="absolute -top-12 -right-12 w-48 h-48 rounded-full blur-3xl opacity-25 pointer-events-none"
          style={{ backgroundColor: form.color }}
        />

        <div className="relative flex items-center gap-5 flex-wrap md:flex-nowrap">
          <div
            className="w-16 h-16 rounded-2xl flex items-center justify-center text-3xl shadow-xl flex-shrink-0"
            style={{
              background: `linear-gradient(135deg, ${form.color}, ${form.color}aa)`,
              boxShadow: `0 8px 30px ${form.color}40`,
            }}
          >
            {form.icon}
          </div>
          <div className="flex-1 min-w-0">
            <h1 className="text-2xl font-black text-white leading-tight">
              {form.name || activeWorkspace.name}
            </h1>
            <p className="text-sm text-slate-400 mt-1 flex items-center gap-2">
              <span>Workspace Settings</span>
              <span className="w-1 h-1 rounded-full bg-slate-700" />
              <span>{totalMembers} collaborators</span>
            </p>
          </div>
        </div>
      </div>

      {/* ── Navigation Tabs ────────────────────────────────────────── */}
      <div className="flex gap-2 p-1.5 rounded-2xl border border-slate-800/60 bg-white/[0.01] overflow-x-auto">
        <TabButton
          label="General Settings"
          active={activeTab === "general"}
          onClick={() => setActiveTab("general")}
          icon={Settings}
        />
        <TabButton
          label="Members"
          active={activeTab === "members"}
          onClick={() => setActiveTab("members")}
          icon={Users}
          badge={totalMembers}
        />
        {canEdit && (
          <TabButton
            label="Invite People"
            active={activeTab === "invite"}
            onClick={() => setActiveTab("invite")}
            icon={UserPlus}
          />
        )}
      </div>

      {/* ── Active Tab View ─────────────────────────────────────────── */}
      <div className="w-full">

        {/* ── Tab: General Settings ───────────────────────────────── */}
        {activeTab === "general" && (
          <form onSubmit={handleSave} className="space-y-6 animate-fade-in">
            {saveError && (
              <div className="px-4 py-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm flex items-center gap-2 animate-fade-in">
                <span className="w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                {saveError}
              </div>
            )}

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">

              {/* Profile Card */}
              <div className="lg:col-span-2 p-6 rounded-2xl border border-slate-800/60 bg-white/[0.02] space-y-6">
                <h3 className="text-base font-bold text-white flex items-center gap-2">
                  <Settings size={16} className="text-violet-400" />
                  Workspace Identity
                </h3>

                <Field label="Workspace Name" description="Give your collaborative environment a clear name.">
                  <input
                    value={form.name}
                    onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
                    disabled={!canEdit}
                    placeholder="e.g. Engineering Team"
                    className="input-field disabled:opacity-50 disabled:cursor-not-allowed"
                  />
                </Field>

                <Field label="Workspace Description" description="Explain what projects or boards are tracked here.">
                  <textarea
                    value={form.description}
                    onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
                    disabled={!canEdit}
                    rows={4}
                    className="input-field resize-none disabled:opacity-50 disabled:cursor-not-allowed"
                    placeholder="e.g. Design boards, dev sprints, and release roadmaps."
                  />
                </Field>
              </div>

              {/* Branding Sidebar Card */}
              <div className="p-6 rounded-2xl border border-slate-800/60 bg-white/[0.02] space-y-6">
                <h3 className="text-base font-bold text-white flex items-center gap-2">
                  <Palette size={16} className="text-violet-400" />
                  Branding Theme
                </h3>

                {/* Icon Grid */}
                <Field label="Icon Selection">
                  <div className="grid grid-cols-5 gap-2 mt-1">
                    {ICONS.map((icon) => (
                      <button
                        key={icon}
                        type="button"
                        onClick={() => canEdit && setForm((f) => ({ ...f, icon }))}
                        className={`aspect-square rounded-xl text-lg flex items-center justify-center transition-all duration-150
                          ${form.icon === icon
                            ? "bg-violet-500/25 ring-2 ring-violet-500 scale-105"
                            : "bg-slate-800/50 border border-slate-700/30 hover:bg-slate-800"
                          }
                          ${!canEdit ? "opacity-40 cursor-not-allowed" : "hover:scale-105"}`}
                      >
                        {icon}
                      </button>
                    ))}
                  </div>
                </Field>

                {/* Color Selection */}
                <Field label="Color Theme">
                  <div className="grid grid-cols-4 gap-3 mt-1">
                    {COLORS.map((color) => (
                      <button
                        key={color}
                        type="button"
                        onClick={() => canEdit && setForm((f) => ({ ...f, color }))}
                        className={`aspect-square rounded-xl transition-all duration-150 relative flex items-center justify-center
                          ${!canEdit ? "opacity-40 cursor-not-allowed" : "hover:scale-105"}`}
                        style={{
                          backgroundColor: color,
                        }}
                      >
                        {form.color === color && (
                          <div className="w-2.5 h-2.5 rounded-full bg-white shadow-md shadow-black/50" />
                        )}
                      </button>
                    ))}
                  </div>
                </Field>

                {/* Brand Preview Box */}
                <div className="pt-4 border-t border-slate-800/40 space-y-3">
                  <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Preview Accent</p>
                  <div
                    className="p-4 rounded-xl border flex items-center gap-3 transition-colors duration-200"
                    style={{
                      background: `linear-gradient(135deg, ${form.color}12, ${form.color}02)`,
                      borderColor: `${form.color}30`,
                    }}
                  >
                    <div
                      className="w-10 h-10 rounded-xl flex items-center justify-center text-xl shadow"
                      style={{ background: form.color }}
                    >
                      {form.icon}
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-bold text-white truncate">{form.name || "Workspace Title"}</p>
                      <p className="text-xs text-slate-500">Live preview</p>
                    </div>
                  </div>
                </div>
              </div>

            </div>

            {canEdit && (
              <div className="flex justify-end border-t border-slate-800/40 pt-4">
                <button
                  type="submit"
                  disabled={saving}
                  className="btn-primary px-8 py-3 shadow-lg shadow-violet-500/20"
                >
                  {saved ? (
                    <><Check size={16} /> Saved Successfully!</>
                  ) : saving ? (
                    <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> Saving Changes…</>
                  ) : (
                    "Save Workspace Details"
                  )}
                </button>
              </div>
            )}
          </form>
        )}

        {/* ── Tab: Members Directory ──────────────────────────────── */}
        {activeTab === "members" && (
          <div className="space-y-6 animate-fade-in">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="text-xl font-black text-white">Members Directory</h2>
                <p className="text-slate-500 text-sm mt-0.5">Below is the complete list of collaborators inside this workspace.</p>
              </div>
            </div>

            {/* List Container */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {activeWorkspace.members?.map((member) => {
                const isYou = member.user?._id === user?._id;
                const meta = ROLE_META[member.role] || ROLE_META.member;
                const RoleIcon = meta.icon;

                return (
                  <div
                    key={member.user?._id || member.user}
                    className="p-4 rounded-2xl border border-slate-800/60 bg-white/[0.02] flex items-center justify-between gap-4 hover:border-slate-700/60 transition-all"
                  >
                    <div className="flex items-center gap-3.5 min-w-0">
                      <Avatar user={member.user} size="md" online={isYou} />
                      <div className="min-w-0">
                        <p className="text-sm font-bold text-white truncate flex items-center gap-2">
                          {member.user?.name || "Unknown"}
                          {isYou && (
                            <span className="text-[10px] font-semibold px-2 py-0.5 rounded bg-violet-500/10 text-violet-400 border border-violet-500/20">
                              You
                            </span>
                          )}
                        </p>
                        <p className="text-xs text-slate-500 truncate mt-0.5">{member.user?.email}</p>
                      </div>
                    </div>

                    <span
                      className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold flex-shrink-0"
                      style={{
                        backgroundColor: meta.bg,
                        color: meta.color,
                        border: `1px solid ${meta.color}25`
                      }}
                    >
                      <RoleIcon size={11} />
                      {meta.label}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ── Tab: Invite Collaborators ──────────────────────────── */}
        {activeTab === "invite" && canEdit && (
          <div className="space-y-6 animate-fade-in">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">

              {/* Form Input Card */}
              <div className="lg:col-span-2 p-6 rounded-2xl border border-slate-800/60 bg-white/[0.02] space-y-6">
                <div>
                  <h2 className="text-lg font-bold text-white">Generate Invitation Link</h2>
                  <p className="text-slate-500 text-xs mt-0.5">Configure email recipients and access roles for secure registration.</p>
                </div>

                <form onSubmit={handleInvite} className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Field label="Email Address" description="Target coworker email address.">
                      <div className="relative">
                        <Mail size={15} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-500" />
                        <input
                          type="email"
                          value={inviteEmail}
                          onChange={(e) => setInviteEmail(e.target.value)}
                          placeholder="name@company.com"
                          className="input-field pl-10"
                        />
                      </div>
                    </Field>

                    <Field label="Workspace Role" description="Configure default permission scope.">
                      <select
                        value={inviteRole}
                        onChange={(e) => setInviteRole(e.target.value)}
                        className="input-field select-field"
                      >
                        <option value="member">Workspace Member (Read & Write)</option>
                        <option value="admin">Workspace Admin (Full access)</option>
                        <option value="viewer">Workspace Viewer (Read only)</option>
                      </select>
                    </Field>
                  </div>

                  <div className="flex justify-end pt-2">
                    <button
                      type="submit"
                      disabled={inviting || !inviteEmail}
                      className="btn-primary px-8 py-3"
                    >
                      <UserPlus size={16} />
                      {inviting ? "Sending Link…" : "Generate & Send Invite"}
                    </button>
                  </div>
                </form>

                {inviteResult && (
                  <div className={`p-4 rounded-xl border text-sm animate-fade-in
                    ${inviteResult.success
                      ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-400"
                      : "bg-red-500/10 border-red-500/20 text-red-400"}`}
                  >
                    {inviteResult.success ? (
                      <div className="space-y-3">
                        <p className="font-semibold flex items-center gap-2">
                          <Check size={16} /> Invite created successfully!
                        </p>
                        <div className="flex items-center gap-2 bg-slate-900/80 px-3 py-2.5 rounded-xl border border-slate-850">
                          <code className="flex-1 text-xs text-slate-300 truncate">
                            {inviteResult.invite?.inviteLink}
                          </code>
                          <button
                            onClick={copyLink}
                            type="button"
                            className={`p-2 rounded-lg transition-all
                              ${copiedLink
                                ? "text-emerald-400 bg-emerald-500/15 border border-emerald-500/25"
                                : "text-slate-400 hover:text-white hover:bg-slate-800"
                              }`}
                          >
                            {copiedLink ? <Check size={14} /> : <Copy size={14} />}
                          </button>
                        </div>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2">
                        <span className="w-1.5 h-1.5 rounded-full bg-red-400 flex-shrink-0" />
                        {inviteResult.message}
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Informative Side Card */}
              <div className="p-6 rounded-2xl border border-slate-800/60 bg-white/[0.02] space-y-4">
                <h3 className="text-sm font-bold text-white flex items-center gap-2">
                  <Globe size={15} className="text-violet-400" />
                  Invitation Scope
                </h3>
                <p className="text-xs text-slate-500 leading-relaxed">
                  Invitations generated allow users to instantly register and access the workspace.
                </p>
                <div className="p-3.5 rounded-xl border border-slate-800 bg-slate-900/20 flex gap-2">
                  <Info size={14} className="text-violet-400 flex-shrink-0 mt-0.5" />
                  <p className="text-[11px] text-slate-500 leading-normal">
                    Generated invitation links automatically expire after 7 days if they remain unclaimed.
                  </p>
                </div>
              </div>

            </div>
          </div>
        )}

      </div>

    </div>
  );
};

export default WorkspaceSettings;
